-- CC_0036_muscogee_county.sql
--
-- Knight Foundation cities program, wave GA-4 Task 4, MUSCOGEE COUNTY --
-- offices AND people in ONE migration, per spec §3.
--   * 1 chamber on the EXISTING Columbus Consolidated Government
--   * 0 districts created -- the countywide district already exists
--   * 5 offices, 5 politicians, 5 terms, 0 vacancies
--
-- Plan:   docs/superpowers/plans/2026-09-01-knight-ga-wave-4-columbus-muscogee.md
