-- --- 3. Politician identity band --------------------------------------------
-- ⚠ SCOPED TO THIS MIGRATION'S OWN SUB-RANGE -1331035..-1331031, NOT to the wave
-- band -1331035..-1331020. Task 3 owns -1331030..-1331020; a guard over the whole
-- wave band would see Task 3's legitimate rows as foreign and break THIS
-- migration's re-run. That is the FL-4 correction.
DO $$
DECLARE v_n int; v_foreign text;
BEGIN
  SELECT count(*), string_agg(external_id::text, ', ' ORDER BY external_id)
    INTO v_n, v_foreign
    FROM essentials.politicians
   WHERE external_id BETWEEN -1331035 AND -1331031
     AND external_id NOT IN (-1331035, -1331034, -1331033, -1331032, -1331031);
  IF v_n <> 0 THEN
    RAISE EXCEPTION 'muscogee county: % row(s) inside this migration''s id range -1331035..-1331031 are owned by something else (%). Pick another sub-range rather than colliding.', v_n, v_foreign;
  END IF;
END $$;

CREATE TEMP TABLE msc_seed (
  geo_id          text,
  mtfcc           text,
  district_type   text,
  office_title    text,
  ext_id          bigint,
  full_name       text,
  first_name      text,
  last_name       text,
  middle_initial  text,
  name_suffix     text,
  aliases         text[],
  term_start      date,
  start_precision text,
  how_started     text,
  source          text
) ON COMMIT DROP;

INSERT INTO msc_seed VALUES
