  ('13215', 'G4020', 'COUNTY', 'Clerk of Superior Court', -1331032, 'Danielle F. Forté', 'Danielle', 'Forté', 'F.', NULL, ARRAY['Danielle F. Forte', 'Danielle Forte', 'Danielle Forté']::text[], NULL::date, 'unknown', 'elected', 'gasos-certified-2024-11-05 + muscogeecourts-biography-live-2026-09-01'),
  ('13215', 'G4020', 'COUNTY', 'Judge of Probate Court', -1331033, 'Marc D''Antonio', 'Marc', 'D''Antonio', NULL, NULL, ARRAY['Marc Eric D''Antonio']::text[], NULL::date, 'unknown', 'elected', 'gasos-certified-2024-11-05 + muscogee-probate-fee-schedule-2025-01-13-authored'),
  ('13215', 'G4020', 'COUNTY', 'Tax Commissioner', -1331034, 'David A. Britt II', 'David', 'Britt', 'A.', 'II', ARRAY['David Britt', 'David A. Britt']::text[], DATE '2025-01-01', 'month', 'elected', 'gasos-certified-2024-11-05 + muscogee-tax-commissioner-office-live-2026-09-01'),
  ('13215', 'G4020', 'COUNTY', 'Coroner', -1331035, 'Buddy Bryan', 'Buddy', 'Bryan', NULL, NULL, ARRAY['Eddie Bryan', 'Eddie Lynwood Bryan']::text[], NULL::date, 'unknown', 'elected', 'gasos-certified-2024-11-05 + georgia-coroners-assoc-directory-live-2026-09-01 + wtvm-2026-08-31');

-- --- 4. Payload guard -------------------------------------------------------
DO $$
DECLARE v_n int; v_dup int;
BEGIN
  SELECT count(*) INTO v_n FROM msc_seed;
  IF v_n <> 5 THEN RAISE EXCEPTION 'muscogee county payload: expected 5 rows, got %', v_n; END IF;

  SELECT count(*) INTO v_dup FROM (SELECT ext_id FROM msc_seed GROUP BY ext_id HAVING count(*) > 1) x;
  IF v_dup <> 0 THEN RAISE EXCEPTION 'muscogee county payload: % duplicate external_id(s)', v_dup; END IF;

  SELECT count(*) INTO v_n FROM msc_seed WHERE ext_id NOT BETWEEN -1331035 AND -1331020;
  IF v_n <> 0 THEN RAISE EXCEPTION 'muscogee county payload: % out-of-band external_id(s)', v_n; END IF;

  SELECT count(*) INTO v_dup FROM (
    SELECT geo_id, mtfcc, district_type, office_title FROM msc_seed
    GROUP BY geo_id, mtfcc, district_type, office_title HAVING count(*) > 1
  ) x;
  IF v_dup <> 0 THEN RAISE EXCEPTION 'muscogee county payload: % duplicate seat key(s)', v_dup; END IF;

  -- 🔴 EVERY ROW IS district_type 'COUNTY'. The city half wrote 'LOCAL' over the
  -- SAME ground, so this is the only column separating the two tiers.
  SELECT count(*) INTO v_n FROM msc_seed WHERE district_type <> 'COUNTY';
  IF v_n <> 0 THEN RAISE EXCEPTION 'muscogee county payload: % row(s) are not district_type COUNTY', v_n; END IF;

  -- A date and its precision must agree in both directions.
  SELECT count(*) INTO v_n FROM msc_seed WHERE term_start IS NULL AND start_precision <> 'unknown';
  IF v_n <> 0 THEN RAISE EXCEPTION 'muscogee county payload: % row(s) have no term_start but claim a precision', v_n; END IF;
  SELECT count(*) INTO v_n FROM msc_seed WHERE term_start IS NOT NULL AND start_precision = 'unknown';
  IF v_n <> 0 THEN RAISE EXCEPTION 'muscogee county payload: % row(s) carry a term_start but declare it unknown', v_n; END IF;

  -- 🔴 EXACTLY 1 ROW IS DATED, AND IT IS THE TAX COMMISSIONER.
  SELECT count(*) INTO v_n FROM msc_seed WHERE term_start IS NOT NULL;
  IF v_n <> 1 THEN RAISE EXCEPTION 'muscogee county payload: expected 1 dated row(s), got %', v_n; END IF;
  SELECT count(*) INTO v_n FROM msc_seed
   WHERE term_start IS NOT NULL AND ext_id NOT IN (-1331034);
  IF v_n <> 0 THEN RAISE EXCEPTION 'muscogee county payload: % dated row(s) are not the expected one', v_n; END IF;

  SELECT count(*) INTO v_n FROM msc_seed
   WHERE how_started NOT IN ('elected','appointed','succeeded','redistricted','unknown');
  IF v_n <> 0 THEN RAISE EXCEPTION 'muscogee county payload: % row(s) carry a how_started the CHECK will refuse', v_n; END IF;

  SELECT count(*) INTO v_n FROM msc_seed WHERE aliases IS NULL;
  IF v_n <> 0 THEN RAISE EXCEPTION 'muscogee county payload: % row(s) carry a NULL aliases array', v_n; END IF;

  SELECT count(*) INTO v_n FROM msc_seed s
   WHERE (SELECT count(*) FROM essentials.offices o
            JOIN essentials.districts d ON d.id = o.district_id
           WHERE d.geo_id = s.geo_id AND d.mtfcc = s.mtfcc
             AND d.district_type = s.district_type AND lower(d.state) = 'ga'
             AND o.title = s.office_title) <> 1;
  IF v_n <> 0 THEN RAISE EXCEPTION 'muscogee county payload: % seat(s) do not resolve to exactly one office', v_n; END IF;
END $$;

-- --- 5. Politicians ---------------------------------------------------------
-- 🔴 IDENTITY IS KEYED ON external_id, NEVER ON NAME. All 5 were checked against
-- production 2026-09-01 and none matched. Near misses are different people:
-- David Cook (TX), Gary Davis, Gary Garrett (UT), David Smith (FL), Gregory
-- Smith (OR), David K. Thompson (WI), Glenn Thompson (PA).
INSERT INTO essentials.politicians
  (external_id, full_name, first_name, last_name, middle_initial, name_suffix,
   alternate_names, is_incumbent, is_active, data_source)
SELECT s.ext_id, s.full_name, s.first_name, s.last_name,
       nullif(s.middle_initial, ''), nullif(s.name_suffix, ''),
       s.aliases, true, true, s.source
FROM msc_seed s
ON CONFLICT (external_id) DO NOTHING;

-- --- 6. Occupancy -----------------------------------------------------------
-- 🔴 TWO PATHS, AND THE SECOND ONE IS NOT A SHORTCUT. seat_officeholder()
-- REFUSES a NULL term_start, and 4 of these 5 have no published start of any
-- kind. Direct insert is safe ONLY into an office with zero existing term rows;
-- the guard REFUSES rather than guesses if that stops being true.
DO $$
DECLARE r record; v_seated int := 0; v_blank int := 0; v_prior int;
BEGIN
  FOR r IN
    SELECT s.term_start, s.start_precision, s.how_started, s.source,
           o.id AS office_id, p.id AS politician_id
      FROM msc_seed s
      JOIN essentials.districts d
        ON d.geo_id = s.geo_id AND d.mtfcc = s.mtfcc
       AND d.district_type = s.district_type AND lower(d.state) = 'ga'
      JOIN essentials.offices o ON o.district_id = d.id AND o.title = s.office_title
      JOIN essentials.politicians p ON p.external_id = s.ext_id
     WHERE NOT EXISTS (
       SELECT 1 FROM essentials.office_terms t
        WHERE t.office_id = o.id AND t.politician_id = p.id
     )
  LOOP
    IF r.term_start IS NOT NULL THEN
      PERFORM essentials.seat_officeholder(
        r.office_id, r.politician_id, r.term_start, r.source, r.how_started, r.start_precision
      );
      v_seated := v_seated + 1;
    ELSE
      IF r.start_precision <> 'unknown' THEN
        RAISE EXCEPTION 'muscogee county: office % has no term_start but claims precision % -- refusing', r.office_id, r.start_precision;
      END IF;
      SELECT count(*) INTO v_prior FROM essentials.office_terms t WHERE t.office_id = r.office_id;
      IF v_prior <> 0 THEN
        RAISE EXCEPTION 'muscogee county: office % already carries % term row(s), so an undated open term cannot be inserted directly -- close the predecessor and give this person a real date', r.office_id, v_prior;
      END IF;
      INSERT INTO essentials.office_terms
        (office_id, politician_id, term_start, term_end, start_precision, how_started, source)
      VALUES (r.office_id, r.politician_id, NULL, NULL, 'unknown', r.how_started, r.source);
      v_blank := v_blank + 1;
    END IF;
  END LOOP;
  RAISE NOTICE 'muscogee county: seated % dated officer(s) via the helper, % with an honest unknown start', v_seated, v_blank;
END $$;

-- --- 7. Post-verify gate ----------------------------------------------------
-- 🔴 SCOPED TO THIS ONE CHAMBER, never to the government: the same government
-- row carries the two CITY chambers, and a government-wide count would couple
-- this migration to them in both directions.
DO $$
DECLARE v_gov uuid; v_ch uuid; v_n int;
BEGIN
  SELECT id INTO v_gov FROM essentials.governments
   WHERE geo_id = '1319000' AND type = 'City';
  IF v_gov IS NULL THEN RAISE EXCEPTION 'muscogee county: the government row is missing'; END IF;

  SELECT id INTO v_ch FROM essentials.chambers
   WHERE government_id = v_gov AND name = 'Muscogee County Elected Officials' AND official_count = 5;
  IF v_ch IS NULL THEN RAISE EXCEPTION 'muscogee county: the Muscogee County Elected Officials chamber is missing or carries the wrong official_count'; END IF;

  SELECT count(*) INTO v_n FROM essentials.offices WHERE chamber_id = v_ch;
  IF v_n <> 5 THEN RAISE EXCEPTION 'muscogee county: expected 5 offices in the chamber, got %', v_n; END IF;

  -- 🔴🔴 THE TIERS MUST NOT HAVE CROSSED. The citywide LOCAL district covers the
  -- SAME 221.011 sq mi as this COUNTY one, so an office landing on the wrong one
  -- would still resolve at an address and look entirely correct.
  SELECT count(*) INTO v_n FROM essentials.offices o
    JOIN essentials.districts d ON d.id = o.district_id
   WHERE o.chamber_id = v_ch
     AND NOT (d.geo_id = '13215' AND d.mtfcc = 'G4020' AND d.district_type = 'COUNTY');
  IF v_n <> 0 THEN RAISE EXCEPTION 'muscogee county: % county office(s) do not sit on 13215/G4020 COUNTY -- the tiers crossed', v_n; END IF;

  -- And the countywide district was not duplicated by this migration.
  SELECT count(*) INTO v_n FROM essentials.districts
   WHERE geo_id = '13215' AND mtfcc = 'G4020' AND district_type = 'COUNTY';
  IF v_n <> 1 THEN RAISE EXCEPTION 'muscogee county: expected exactly 1 Muscogee County COUNTY district, got %', v_n; END IF;

  -- ⚠ COUNT THIS MIGRATION'S OWN IDS, NOT THE WHOLE BAND.
  SELECT count(*) INTO v_n FROM essentials.politicians WHERE external_id IN (-1331035, -1331034, -1331033, -1331032, -1331031);
  IF v_n <> 5 THEN RAISE EXCEPTION 'muscogee county: expected 5 of this migration''s politicians, got %', v_n; END IF;

  -- 🔴 count(och.politician_id), NOT count(*): office_current_holder LEFT JOINs
  -- from offices, so a vacancy is a NULL politician_id and count(*) passes
  -- VACUOUSLY on an entirely unseated chamber.
  SELECT count(och.politician_id) INTO v_n
    FROM essentials.offices o
    LEFT JOIN essentials.office_current_holder och ON och.office_id = o.id
   WHERE o.chamber_id = v_ch;
  IF v_n <> 5 THEN RAISE EXCEPTION 'muscogee county: expected 5 seated officers, found %', v_n; END IF;

  SELECT count(*) INTO v_n FROM essentials.offices WHERE chamber_id = v_ch AND is_vacant = true;
  IF v_n <> 0 THEN RAISE EXCEPTION 'muscogee county: % officer seat(s) flagged vacant, expected 0', v_n; END IF;

  -- The 4 undated terms are open-ended at 'unknown', with NO term_end: a
  -- future term_end makes a seat silently self-vacate on a date nobody watches.
  SELECT count(*) INTO v_n
    FROM essentials.office_terms t
    JOIN essentials.politicians p ON p.id = t.politician_id
   WHERE p.external_id IN (-1331035, -1331033, -1331032, -1331031)
     AND (t.start_precision <> 'unknown' OR t.term_start IS NOT NULL OR t.term_end IS NOT NULL);
  IF v_n <> 0 THEN RAISE EXCEPTION 'muscogee county: % term row(s) that should be open-ended unknown are not', v_n; END IF;

  -- And the dated one carries exactly the date that was sourced, at the
  -- precision the source actually supports.
  SELECT count(*) INTO v_n
    FROM essentials.office_terms t
    JOIN essentials.politicians p ON p.id = t.politician_id
   WHERE p.external_id = -1331034
     AND t.term_start = DATE '2025-01-01'
     AND t.start_precision = 'month'
     AND t.how_started = 'elected'
     AND t.term_end IS NULL;
  IF v_n <> 1 THEN RAISE EXCEPTION 'muscogee county: David A. Britt II (-1331034) does not hold exactly one open term starting 2025-01-01 at month precision, got %', v_n; END IF;

  -- No officer seat may be left with no term row: that is the invisible-office
  -- failure, and nothing else errors.
  SELECT count(*) INTO v_n FROM essentials.offices o
   WHERE o.chamber_id = v_ch
     AND NOT EXISTS (SELECT 1 FROM essentials.office_terms t WHERE t.office_id = o.id);
  IF v_n <> 0 THEN RAISE EXCEPTION 'muscogee county: % officer seat(s) carry no office_terms row and are invisible', v_n; END IF;

  RAISE NOTICE 'muscogee county OK: 1 chamber, 5 offices, 5 officers seated, 0 vacancies, 0 districts created';
END $$;

COMMIT;
